/* Goalspace single-page static app. UI modules share one local data model. */
(()=>{
 const store=window.GoalStore;let data=store.load(),page='dashboard',calendarDate=new Date(),selectedDate=store.today(),editingGoal=null,quoteIndex=0;
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],today=store.today();
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=d=>{if(!d)return 'No deadline';let x=new Date(d+'T12:00:00');return x.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})};
 const daysUntil=d=>Math.ceil((new Date(d+'T12:00:00')-new Date(today+'T12:00:00'))/86400000);
 const active=()=>data.goals.filter(g=>g.status==='Active'),completed=()=>data.goals.filter(g=>g.status==='Completed');
 const pct=()=>data.goals.length?Math.round(data.goals.reduce((a,g)=>a+Number(g.progress||0),0)/data.goals.length):0;
 const initials=n=>(n||'A').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
 function persist(){store.save(data);updateChrome()}
 function updateChrome(){const n=initials(data.profile.name),photo=data.profile.photo;if(photo){$('#sideAvatar').innerHTML=`<img src="${esc(photo)}" alt="">`;$('#topAvatar').innerHTML=`<img src="${esc(photo)}" alt="">`}else{$('#sideAvatar').textContent=n;$('#topAvatar').textContent=n;}const removePhoto=$('#removeProfilePhoto');if(removePhoto)removePhoto.disabled=!photo;$('#goalNavCount').textContent=active().length;const u=data.notifications.filter(x=>!x.read).length;$('#notificationCount').textContent=u;$('#bellDot').style.display=u?'block':'none';document.body.classList.toggle('dark',!!data.settings.dark);document.body.classList.toggle('no-motion',!data.settings.animations)}
 const catColor=c=>({'Fitness':'mint','Finance':'amber','Career':'coral','Study':'blue','Personal Development':'purple','Habits':'mint','Projects':'coral'}[c]||'blue');
 const statusOf=g=>g.status==='Completed'?'completed':g.status==='Paused'?'paused':g.deadline<today?'overdue':'active';
 const dueLabel=g=>{if(g.status==='Completed')return 'Completed';const n=daysUntil(g.deadline);return n<0?`${Math.abs(n)} days overdue`:n===0?'Due today':`${n} days left`};
 function pageHeading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${page==='dashboard'?'YOUR PERSONAL SPACE':'GOALSPACE'}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
 function setPage(name){page=name;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===name));$('#breadcrumbPage').textContent=({dashboard:'Dashboard',goals:'My Goals',create:editingGoal?'Edit Goal':'Create Goal',progress:'Progress Tracker',habits:'Habit Tracker',calendar:'Calendar',achievements:'Achievements',reports:'Reports',notifications:'Notifications',profile:'Profile',settings:'Settings'})[name]||'Dashboard';$('#sidebar').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'smooth'})}
 function render(){updateChrome();const root=$('#pageContent');root.innerHTML=({dashboard:renderDashboard,goals:renderGoals,create:renderCreate,progress:renderProgress,habits:renderHabits,calendar:renderCalendar,achievements:renderAchievements,reports:renderReports,notifications:renderNotifications,profile:renderProfile,settings:renderSettings}[page]||renderDashboard)();bindPage()}
 function renderDashboard(){const a=active(),done=completed(),avg=pct(),allMilestones=data.goals.flatMap(g=>g.milestones||[]),doneMs=allMilestones.filter(m=>m.done).length;const sorted=[...a].sort((x,y)=>x.deadline.localeCompare(y.deadline));const habitDone=data.habits.filter(h=>(h.checkins||[]).includes(today)).length;const categories=[...new Set(data.goals.map(g=>g.category))].slice(0,4);return `${pageHeading(`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(data.profile.name.split(' ')[0])} 👋`,'You’re making progress, one step at a time.',`<button class="btn btn-secondary" data-action="checkin-all">✓ Check in today</button><button class="btn btn-primary" data-page="create">＋ New goal</button>`)}
 <section class="stats-grid"><article class="stat-card"><div class="stat-top">Active goals<span class="stat-icon purple">◎</span></div><div class="stat-value">${a.length}<span class="stat-note">in progress</span></div><div class="stat-bottom">${done.length} completed so far</div></article><article class="stat-card"><div class="stat-top">Overall progress<span class="stat-icon green">↗</span></div><div class="stat-value">${avg}%</div><div class="stat-bottom"><span class="up">↑ steady progress</span> across all goals</div></article><article class="stat-card"><div class="stat-top">Habits today<span class="stat-icon orange">✓</span></div><div class="stat-value">${habitDone}<span class="stat-note">of ${data.habits.length} done</span></div><div class="stat-bottom">${data.habits.length?Math.round(habitDone/data.habits.length*100):0}% of today’s plan</div></article><article class="stat-card"><div class="stat-top">Current streak<span class="stat-icon blue">✦</span></div><div class="stat-value">${bestCurrentStreak()}<span class="stat-note">days</span></div><div class="stat-bottom">You’re building consistency</div></article></section>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Progress overview</h2><div class="panel-sub">A little better every day</div></div><button class="text-link" data-page="progress">View details →</button></div><div class="progress-overview"><div class="ring" style="--pct:${avg}"><div class="ring-content"><strong>${avg}%</strong><span>overall progress</span></div></div><div class="progress-legend"><div class="legend-row"><span class="legend-key"><i class="legend-dot" style="background:var(--primary)"></i>Active goals</span><strong>${a.length}</strong></div><div class="legend-row"><span class="legend-key"><i class="legend-dot" style="background:var(--mint)"></i>Completed goals</span><strong>${done.length}</strong></div><div class="legend-row"><span class="legend-key"><i class="legend-dot" style="background:var(--amber)"></i>Milestones reached</span><strong>${doneMs}/${allMilestones.length}</strong></div>${categories.slice(0,2).map(c=>`<div class="legend-row"><span class="legend-key"><i class="legend-dot" style="background:var(--coral)"></i>${esc(c)}</span><strong>${data.goals.filter(g=>g.category===c).length}</strong></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Goals in motion</h2><div class="panel-sub">Your active focus areas</div></div><button class="text-link" data-page="goals">All goals →</button></div><div class="goal-summary">${a.slice(0,4).map(g=>`<div class="goal-summary-row"><div class="goal-summary-title">${esc(g.title)}</div><span class="goal-summary-pct">${g.progress}%</span><div class="mini-track ${catColor(g.category)}"><span style="width:${g.progress}%"></span></div></div>`).join('')||'<div class="empty-inline">No active goals yet.</div>'}</div></section></div>
 <div class="habits-deadline-grid"><section class="panel"><div class="panel-head"><div><h2>Today’s habits</h2><div class="panel-sub">Small actions, meaningful change</div></div><button class="text-link" data-page="habits">Habit tracker →</button></div><div class="habit-today-list">${data.habits.slice(0,4).map(h=>{let checked=(h.checkins||[]).includes(today);return `<div class="habit-row"><button class="check-circle ${checked?'done':''}" data-check-habit="${h.id}" aria-label="${checked?'Undo':'Complete'} ${esc(h.name)}">${checked?'✓':''}</button><div class="habit-row-text"><strong>${esc(h.name)}</strong><small>${esc(h.category)}</small></div><span class="streak">🔥 ${calcStreak(h)} day${calcStreak(h)===1?'':'s'}</span></div>`}).join('')||'<div class="empty-inline">Create a habit to start building your routine.</div>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Coming up</h2><div class="panel-sub">Keep an eye on these dates</div></div><button class="text-link" data-page="calendar">Calendar →</button></div><div class="deadline-list">${sorted.slice(0,3).map(g=>{let d=daysUntil(g.deadline);let dt=new Date(g.deadline+'T12:00:00');return `<div class="deadline-row"><div class="date-chip"><strong>${dt.getDate()}</strong><span>${dt.toLocaleDateString(undefined,{month:'short'})}</span></div><div class="deadline-info"><strong>${esc(g.title)}</strong><small>${d<0?'Overdue':d===0?'Due today':`Due in ${d} days`}</small></div><span class="deadline-tag">${esc(g.category)}</span></div>`}).join('')||'<div class="empty-inline">No deadlines coming up.</div>'}</div></section></div>
 ${data.settings.quote?`<section class="quote-card"><div><div class="quote-label">A little encouragement</div><p id="quoteText">“${quotes[quoteIndex%quotes.length][0]}”</p><small id="quoteAuthor">— ${quotes[quoteIndex%quotes.length][1]}</small></div><button class="quote-refresh" data-action="quote" aria-label="Show another quote">↻</button></section>`:''}`}
 const quotes=[['Great things are done by a series of small things brought together.','Vincent van Gogh'],['You do not have to see the whole staircase, just take the first step.','Martin Luther King Jr.'],['It always seems impossible until it’s done.','Nelson Mandela'],['Success is the sum of small efforts, repeated day in and day out.','Robert Collier'],['The secret of getting ahead is getting started.','Mark Twain']];
 function bestCurrentStreak(){return Math.max(0,...data.habits.map(calcStreak))}
 function calcStreak(h){const checks=new Set(h.checkins||[]);let d=new Date(today+'T12:00:00');if(!checks.has(today))d.setDate(d.getDate()-1);let n=0;while(checks.has(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n}
 function goalCard(g){return `<article class="goal-card"><div class="goal-card-top"><span class="category-pill ${catColor(g.category)}">${esc(g.category)}</span><button class="more-button" data-goal-detail="${g.id}" aria-label="Open ${esc(g.title)}">···</button></div><h3>${esc(g.title)}</h3><p class="goal-desc">${esc(g.description||'No description added.')}</p><div class="goal-card-meta"><span>Progress</span><strong>${g.progress}%</strong></div><div class="progress-track"><span style="width:${g.progress}%;background:${g.progress>=100?'var(--mint)':undefined}"></span></div><div class="goal-card-meta"><span>◷ ${esc(dueLabel(g))}</span><span class="priority-pill">${esc(g.priority||'Medium')} priority</span></div><div class="goal-card-foot"><span class="goal-card-date">Updated ${fmt(g.updated||g.start)}</span><div class="goal-actions"><button data-goal-detail="${g.id}">Details</button><button data-edit-goal="${g.id}">Edit</button></div></div></article>`}
 function renderGoals(){return `${pageHeading('My goals','Keep your focus visible and your next step clear.',`<button class="btn btn-primary" data-page="create">＋ Create goal</button>`)}<section class="panel"><div class="filters"><input class="input search-input" id="goalSearch" placeholder="⌕  Search your goals…" aria-label="Search goals"><select class="select" id="categoryFilter"><option value="">All categories</option>${data.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select class="select" id="statusFilter"><option value="">All statuses</option><option>Active</option><option>Completed</option><option>Paused</option><option>Overdue</option></select><select class="select" id="priorityFilter"><option value="">All priorities</option><option>High</option><option>Medium</option><option>Low</option></select><select class="select" id="sortGoals"><option value="deadline">Deadline soonest</option><option value="progress">Progress</option><option value="priority">Priority</option><option value="updated">Recently updated</option></select></div><div class="goal-grid" id="goalGrid">${data.goals.map(goalCard).join('')||emptyState('No goals yet','Create your first goal and make a plan for what comes next.')}</div></section>`}
 function emptyState(title,msg){return `<div class="empty-state"><div class="empty-icon">✧</div><h3>${title}</h3><p>${msg}</p><button class="btn btn-primary" data-page="create">＋ Create a goal</button></div>`}
 function renderCreate(){const g=editingGoal?data.goals.find(x=>x.id===editingGoal):null;return `${pageHeading(g?'Edit your goal':'Create a goal',g?'Adjust your plan and keep moving forward.':'Start with a clear intention. You can refine the plan as you go.') }<div class="form-layout"><section class="panel form-panel"><form id="goalForm"><div class="form-grid"><div class="field full"><label for="goalTitle">Goal title *</label><input class="input" id="goalTitle" name="title" maxlength="90" required placeholder="e.g. Finish my biology course" value="${esc(g?.title||'')}"></div><div class="field full"><label for="goalDescription">Description</label><textarea class="textarea" id="goalDescription" name="description" maxlength="350" placeholder="What does success look like for you?">${esc(g?.description||'')}</textarea></div><div class="field"><label for="goalCategory">Category *</label><select class="select" id="goalCategory" name="category" required>${data.categories.map(c=>`<option ${g?.category===c?'selected':''}>${esc(c)}</option>`).join('')}<option value="__custom">＋ Add custom category…</option></select></div><div class="field"><label for="goalPriority">Priority</label><select class="select" id="goalPriority" name="priority">${['Low','Medium','High'].map(x=>`<option ${g?.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="goalStart">Start date</label><input class="input" type="date" id="goalStart" name="start" value="${esc(g?.start||today)}"></div><div class="field"><label for="goalDeadline">Target date</label><input class="input" type="date" id="goalDeadline" name="deadline" value="${esc(g?.deadline||store.date(30))}"></div><div class="field full"><label for="goalProgress">Initial progress <span id="progressValue">${g?.progress||0}%</span></label><input id="goalProgress" name="progress" type="range" min="0" max="100" value="${g?.progress||0}" style="accent-color:var(--primary)"></div><div class="field full"><span class="field-label">Milestones</span><div class="milestone-editor" id="milestoneEditor">${(g?.milestones||[{title:'',done:false}]).map((m,i)=>milestoneInput(m,i)).join('')}</div><button class="btn btn-secondary" type="button" data-action="add-milestone">＋ Add milestone</button></div><div class="field full"><label for="goalNotes">Notes</label><textarea class="textarea" id="goalNotes" name="notes" placeholder="Useful reminders, links, or thoughts…">${esc(g?.notes||'')}</textarea></div><div class="field full"><label class="check-option"><input type="checkbox" name="reminder" ${g?.reminder?'checked':''}> Remind me 3 days before the target date</label></div></div><div class="form-actions"><button class="btn btn-secondary" type="button" data-action="cancel-goal">Cancel</button><button class="btn btn-primary" type="submit">${g?'Save changes':'Create goal'}</button></div></form></section><aside class="tip-panel"><span class="stat-icon purple">✦</span><h3>Make it achievable</h3><p>Clear goals are easier to act on. Break bigger ambitions into steps you can complete one at a time.</p><div class="tip-list"><div class="tip-row"><span>✓</span> Choose a specific outcome</div><div class="tip-row"><span>✓</span> Set a realistic target date</div><div class="tip-row"><span>✓</span> Add a few milestones</div><div class="tip-row"><span>✓</span> Track your progress often</div></div></aside></div>`}
 function milestoneInput(m,i){return `<div class="milestone-edit-row"><input class="input milestone-field" maxlength="80" placeholder="Milestone ${i+1}" value="${esc(m.title||'')}"><button type="button" data-action="remove-milestone" aria-label="Remove milestone">×</button></div>`}
 function bindPage(){
   $$('[data-goal-detail]').forEach(b=>b.onclick=()=>openGoal(b.dataset.goalDetail));$$('[data-edit-goal]').forEach(b=>b.onclick=()=>{editingGoal=b.dataset.editGoal;setPage('create')});
   $$('[data-check-habit]').forEach(b=>b.onclick=()=>toggleHabit(b.dataset.checkHabit));
   $$('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));
   const form=$('#goalForm');if(form){$('#goalProgress').oninput=e=>$('#progressValue').textContent=e.target.value+'%';$('#goalCategory').onchange=e=>{if(e.target.value==='__custom'){let c=prompt('Name your new category');if(c&&c.trim()){if(!data.categories.includes(c.trim()))data.categories.push(c.trim());e.target.innerHTML=data.categories.map(x=>`<option>${esc(x)}</option>`).join('');e.target.value=c.trim()}else e.target.value=data.categories[0]}};form.onsubmit=saveGoal;}
   ['goalSearch','categoryFilter','statusFilter','priorityFilter','sortGoals'].forEach(id=>{let el=$('#'+id);if(el)el.oninput=filterGoals});
   const hf=$('#habitForm');if(hf)hf.onsubmit=saveHabit;
   const pf=$('#profileForm');if(pf)pf.onsubmit=saveProfile;const photoInput=$('#profilePhotoInput');if(photoInput)photoInput.onchange=saveProfilePhoto;
   $$('[data-setting]').forEach(b=>b.onclick=()=>changeSetting(b.dataset.setting));const accent=$('#accentSelect');if(accent)accent.onchange=()=>{data.settings.accent=accent.value;applyAccent();persist()};const importFile=$('#importFile');if(importFile)importFile.onchange=handleImport;
   $$('[data-notify-action]').forEach(b=>b.onclick=()=>notificationAction(b.dataset.notifyAction,b.dataset.id));
   $$('[data-cal-nav]').forEach(b=>b.onclick=()=>{calendarDate.setMonth(calendarDate.getMonth()+Number(b.dataset.calNav));render()});$$('[data-cal-day]').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.calDay;render()});
 }
 function handleAction(action,button){switch(action){case'quote':quoteIndex++;let q=quotes[quoteIndex%quotes.length];$('#quoteText').textContent='“'+q[0]+'”';$('#quoteAuthor').textContent='— '+q[1];break;case'add-milestone':$('#milestoneEditor').insertAdjacentHTML('beforeend',milestoneInput({},$$('.milestone-edit-row').length));break;case'remove-milestone':if($$('.milestone-edit-row').length>1)button.closest('.milestone-edit-row').remove();else button.previousElementSibling.value='';break;case'cancel-goal':editingGoal=null;setPage('goals');break;case'checkin-all':data.habits.forEach(h=>{if(!h.checkins.includes(today))h.checkins.push(today)});addActivity('Checked in for all habits today');persist();render();toast('All habits checked in. Great work!');checkAchievements();break;case'add-habit':openHabitForm();break;case'export':exportData();break;case'import':$('#importFile').click();break;case'reset':if(confirm('Reset all Goalspace data to the starter example? This cannot be undone.')){localStorage.removeItem(store.key);data=store.load();toast('Your starter data has been restored.');render()}break;case'print':window.print();break;case'global-search':setPage('goals');setTimeout(()=>$('#goalSearch')?.focus(),80);break;case'cancel-modal':closeModal();break;case'edit-profile':document.getElementById('profileName')?.focus();break;case'upload-photo':$('#profilePhotoInput')?.click();break;case'remove-photo':data.profile.photo='';persist();render();toast('Profile picture removed.');break}}
 function saveGoal(e){e.preventDefault();const fd=new FormData(e.currentTarget),title=fd.get('title').trim(),start=fd.get('start'),deadline=fd.get('deadline');if(!title){toast('Add a title for your goal.');return}if(start&&deadline&&deadline<start){toast('Target date should come after the start date.');return}const ms=$$('.milestone-field').map(x=>x.value.trim()).filter(Boolean);let g=editingGoal&&data.goals.find(x=>x.id===editingGoal);const before=g?.progress||0;if(g){Object.assign(g,{title,description:fd.get('description').trim(),category:fd.get('category'),priority:fd.get('priority'),start,deadline,progress:Number(fd.get('progress')),status:Number(fd.get('progress'))>=100?'Completed':g.status==='Completed'?'Active':g.status,milestones:ms.map((t,i)=>({id:g.milestones?.[i]?.id||id('m'),title:t,done:g.milestones?.[i]?.done||false})),notes:fd.get('notes').trim(),reminder:fd.has('reminder'),updated:today});if(before!==g.progress)g.history.push({date:today,progress:g.progress});if(g.progress>=100){g.milestones.forEach(m=>m.done=true);if(before<100)notify('Goal completed',`${g.title} is complete. Well done!`,'complete')}addActivity(`Updated goal: ${title}`)}else{g={id:id('g'),title,description:fd.get('description').trim(),category:fd.get('category'),priority:fd.get('priority'),start,deadline,progress:Number(fd.get('progress')),status:Number(fd.get('progress'))>=100?'Completed':'Active',milestones:ms.map(t=>({id:id('m'),title:t,done:false})),notes:fd.get('notes').trim(),reminder:fd.has('reminder'),updated:today,history:[{date:today,progress:Number(fd.get('progress'))}],habits:[]};data.goals.unshift(g);addActivity(`Created goal: ${title}`)}persist();editingGoal=null;setPage('goals');toast('Goal saved. Keep taking the next step.');checkAchievements()}
 function filterGoals(){const q=($('#goalSearch')?.value||'').toLowerCase(),cat=$('#categoryFilter')?.value||'',st=$('#statusFilter')?.value||'',pr=$('#priorityFilter')?.value||'',sort=$('#sortGoals')?.value||'deadline';let list=data.goals.filter(g=>(`${g.title} ${g.description} ${g.category}`.toLowerCase().includes(q))&&(!cat||g.category===cat)&&(!pr||g.priority===pr)&&(!st|| (st==='Overdue'?g.status!=='Completed'&&g.deadline<today:g.status===st)));list.sort((a,b)=>sort==='progress'?b.progress-a.progress:sort==='priority'?({High:0,Medium:1,Low:2}[a.priority]-{High:0,Medium:1,Low:2}[b.priority]):sort==='updated'?b.updated.localeCompare(a.updated):a.deadline.localeCompare(b.deadline));$('#goalGrid').innerHTML=list.map(goalCard).join('')||emptyState('No goals match','Try changing your search or filters.');$$('[data-goal-detail]').forEach(b=>b.onclick=()=>openGoal(b.dataset.goalDetail));$$('[data-edit-goal]').forEach(b=>b.onclick=()=>{editingGoal=b.dataset.editGoal;setPage('create')})}
 function openGoal(goalId){const g=data.goals.find(x=>x.id===goalId);if(!g)return;const remaining=daysUntil(g.deadline),milestones=g.milestones||[];$('#modalContent').innerHTML=`<div class="eyebrow">${esc(g.category)} · ${esc(g.priority)} priority</div><h2 id="modalTitle">${esc(g.title)}</h2><p class="modal-desc">${esc(g.description||'No description provided.')}</p>${g.progress===100?'<div class="celebration"><span>🎉</span><br><strong>You did it! This goal is complete.</strong></div>':''}<div class="detail-progress"><div class="progress-track"><span style="width:${g.progress}%;background:${g.progress===100?'var(--mint)':''}"></span></div><strong>${g.progress}%</strong></div><div class="detail-progress-form"><label class="field-label" for="detailProgress">Update progress</label><div style="display:flex;gap:10px;align-items:center;margin-top:7px"><input id="detailProgress" type="range" min="0" max="100" value="${g.progress}" style="flex:1;accent-color:var(--primary)"><button class="btn btn-primary" data-action="save-detail-progress" data-id="${g.id}">Save</button></div></div><div class="detail-section"><h3>Target date</h3><div style="font-size:12px;color:var(--muted)">${fmt(g.deadline)} · ${remaining<0?`${Math.abs(remaining)} days overdue`:remaining===0?'Due today':`${remaining} days remaining`}</div></div><div class="detail-section"><h3>Milestones (${milestones.filter(m=>m.done).length}/${milestones.length})</h3><div class="milestone-list">${milestones.map(m=>`<label class="milestone-row"><input type="checkbox" data-milestone="${m.id}" ${m.done?'checked':''}>${esc(m.title)}<small>${m.done?'Complete':'Not yet'}</small></label>`).join('')||'<span class="field-help">No milestones added.</span>'}</div></div><div class="detail-section"><h3>Notes</h3><p class="modal-desc">${esc(g.notes||'No notes yet.')}</p></div><div class="form-actions"><button class="btn btn-danger" data-action="delete-goal" data-id="${g.id}">Delete</button><button class="btn btn-secondary" data-action="toggle-pause" data-id="${g.id}">${g.status==='Paused'?'Resume':'Pause'}</button><button class="btn btn-primary" data-action="edit-from-detail" data-id="${g.id}">Edit goal</button></div>`;
   $('#modalBackdrop').hidden=false;$$('[data-action]', $('#modalContent')).forEach(b=>b.onclick=()=>{let act=b.dataset.action,id0=b.dataset.id;if(act==='save-detail-progress'){let p=Number($('#detailProgress').value);g.progress=p;g.updated=today;g.history.push({date:today,progress:p});if(p>=100){g.status='Completed';g.milestones.forEach(m=>m.done=true);notify('Goal completed',`${g.title} is complete. Well done!`,'complete')}addActivity(`Updated ${g.title} to ${p}%`);persist();checkAchievements();openGoal(id0);toast(p===100?'Goal complete — celebrate this moment!':'Progress saved.')}if(act==='delete-goal'&&confirm('Delete this goal?')){data.goals=data.goals.filter(x=>x.id!==id0);addActivity(`Deleted goal: ${g.title}`);persist();closeModal();render();toast('Goal deleted.')}if(act==='toggle-pause'){g.status=g.status==='Paused'?'Active':'Paused';g.updated=today;persist();openGoal(id0);render();toast(g.status==='Paused'?'Goal paused.':'Goal resumed.')}if(act==='edit-from-detail'){closeModal();editingGoal=id0;setPage('create')}});$$('[data-milestone]', $('#modalContent')).forEach(c=>c.onchange=()=>{let m=milestones.find(x=>x.id===c.dataset.milestone);m.done=c.checked;g.updated=today;addActivity(`${m.done?'Completed':'Reopened'} milestone: ${m.title}`);persist();checkAchievements();openGoal(goalId)})
 }
 function closeModal(){$('#modalBackdrop').hidden=true}
 function id(prefix){return prefix+'-'+Math.random().toString(36).slice(2,9)}
 function addActivity(text){data.activity.unshift({text,date:today});data.activity=data.activity.slice(0,80)}
 function notify(title,message,type){data.notifications.unshift({id:id('n'),title,message,date:today,read:false,type})}
 function checkAchievements(){const allM=data.goals.flatMap(g=>g.milestones||[]),unlocks=[];const test=(code,ok,title,msg)=>{if(ok&&!data.achievements.includes(code)){data.achievements.push(code);unlocks.push([title,msg])}};test('first-goal',data.goals.length>0,'First step','You created your first goal.');test('first-milestone',allM.some(m=>m.done),'Milestone moment','You completed your first milestone.');test('first-complete',completed().length>0,'Goal getter','You completed your first goal.');test('quarter-progress',pct()>=25,'Quarter way there','You reached 25% average progress.');test('half-progress',pct()>=50,'Halfway hero','You reached 50% average progress.');test('three-quarter-progress',pct()>=75,'Almost there','You reached 75% average progress.');test('hundred-progress',pct()>=100,'All complete','Every goal reached 100%.');test('five-goals',completed().length>=5,'Five in the bag','You completed five goals.');test('ten-goals',completed().length>=10,'Ten goals down','You completed ten goals.');test('habit-week',data.habits.some(h=>{const checks=new Set(h.checkins||[]);return Array.from({length:7},(_,i)=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()-i);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}).every(day=>checks.has(day))}),'Steady routine','You checked in every day for a week.');test('week-streak',bestCurrentStreak()>=7,'One week strong','You reached a 7-day habit streak.');test('month-streak',bestCurrentStreak()>=30,'A month of momentum','You reached a 30-day habit streak.');unlocks.forEach(x=>{notify('Achievement unlocked',x[0]+': '+x[1],'achievement');addActivity('Unlocked achievement: '+x[0])});if(unlocks.length)persist()}
 function toggleHabit(hid){let h=data.habits.find(x=>x.id===hid);if(!h)return;h.checkins=h.checkins||[];if((h.checkins||[]).includes(today))h.checkins=h.checkins.filter(d=>d!==today);else{h.checkins.push(today);addActivity(`Checked in: ${h.name}`)}persist();checkAchievements();render();toast(h.checkins.includes(today)?'Habit checked in. Nice work!':'Check-in removed.')}
 function renderProgress(){const av=pct(),all=data.goals.flatMap(g=>g.milestones||[]),done=all.filter(m=>m.done).length,cats=[...new Set(data.goals.map(g=>g.category))],weekLabels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let bars=weekLabels.map((label,i)=>{let values=data.goals.flatMap(g=>g.history||[]).filter(h=>new Date(h.date+'T12:00:00').getDay()===(i+1)%7);let v=values.length?Math.min(100,Math.max(...values.map(x=>x.progress))):[24,41,34,65,51,72,58][i];return `<div class="bar-group"><span class="bar alt" style="height:${Math.max(6,v*.72)}%"></span><span class="bar" style="height:${Math.max(6,v)}%"></span></div>`}).join('');return `${pageHeading('Progress tracker','See what’s moving forward and where you can focus next.',`<button class="btn btn-secondary" data-action="print">⤓ Print report</button>`)}<section class="stats-grid"><article class="stat-card"><div class="stat-top">Overall completion<span class="stat-icon purple">◒</span></div><div class="stat-value">${av}%</div><div class="stat-bottom">Across ${data.goals.length} goals</div></article><article class="stat-card"><div class="stat-top">Goals completed<span class="stat-icon green">✓</span></div><div class="stat-value">${completed().length}</div><div class="stat-bottom">of ${data.goals.length} total goals</div></article><article class="stat-card"><div class="stat-top">Milestones reached<span class="stat-icon orange">✧</span></div><div class="stat-value">${done}<span class="stat-note">of ${all.length}</span></div><div class="stat-bottom">${all.length?Math.round(done/all.length*100):0}% complete</div></article><article class="stat-card"><div class="stat-top">Current streak<span class="stat-icon blue">🔥</span></div><div class="stat-value">${bestCurrentStreak()}<span class="stat-note">days</span></div><div class="stat-bottom">Across your habits</div></article></section><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Weekly progress</h2><div class="panel-sub">Goal work and progress by day</div></div><span class="category-pill">This week</span></div><div class="chart-bars">${bars}</div><div class="bar-labels">${weekLabels.map(x=>`<span>${x}</span>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Goals by category</h2><div class="panel-sub">Average progress in each area</div></div></div><div class="category-analysis">${cats.map(c=>{let list=data.goals.filter(g=>g.category===c),v=Math.round(list.reduce((a,g)=>a+g.progress,0)/list.length);return `<div class="category-line"><span>${esc(c)}</span><div class="progress-track"><span style="width:${v}%;background:var(--${catColor(c)==='mint'?'mint':catColor(c)==='amber'?'amber':catColor(c)==='coral'?'coral':'primary'})"></span></div><strong>${v}%</strong></div>`}).join('')||'<p class="field-help">Add goals to see category progress.</p>'}</div></section></div><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Progress history</h2><div class="panel-sub">Recent goal updates</div></div></div>${data.activity.slice(0,7).map(a=>`<div class="notification-row"><div class="notification-icon">↗</div><div class="notification-body"><strong>${esc(a.text)}</strong><small>${fmt(a.date)}</small></div></div>`).join('')||'<div class="empty-inline">Your updates will show here.</div>'}</section><section class="panel"><div class="panel-head"><div><h2>Monthly snapshot</h2><div class="panel-sub">Your goal momentum</div></div></div><div class="goal-summary"><div class="legend-row"><span class="legend-key">Active goals</span><strong>${active().length}</strong></div><div class="legend-row"><span class="legend-key">Completed goals</span><strong>${completed().length}</strong></div><div class="legend-row"><span class="legend-key">Habit completion</span><strong>${habitRate()}%</strong></div><div class="legend-row"><span class="legend-key">Milestones completed</span><strong>${done}/${all.length}</strong></div></div></section></div>`}
 function habitRate(){let all=data.habits.reduce((n,h)=>n+(h.checkins||[]).length,0);let possible=data.habits.length*Math.max(1,Math.min(30,Math.ceil((new Date()-new Date(data.createdAt+'T12:00:00'))/86400000)));return Math.min(100,Math.round(all/possible*100))}
 function renderHabits(){const month=new Date(),days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return d});return `${pageHeading('Habit tracker','Build routines that make your bigger goals easier.',`<button class="btn btn-primary" data-action="add-habit">＋ Add habit</button>`)}<div class="habit-page-grid"><section class="panel"><div class="panel-head"><div><h2>Your habits</h2><div class="panel-sub">Tap a circle to check in for today</div></div><span class="category-pill mint">${data.habits.filter(h=>h.checkins.includes(today)).length}/${data.habits.length} today</span></div>${data.habits.map(h=>`<div class="habit-card"><button class="check-circle ${h.checkins.includes(today)?'done':''}" data-check-habit="${h.id}" aria-label="Check in ${esc(h.name)}">${h.checkins.includes(today)?'✓':''}</button><div class="habit-emoji">${h.emoji||'✧'}</div><div class="habit-card-info"><strong>${esc(h.name)}</strong><small>${esc(h.frequency)} · ${esc(h.category)}${h.goalId?' · '+esc(data.goals.find(g=>g.id===h.goalId)?.title||''):''}</small></div><div class="habit-stat">🔥 ${calcStreak(h)} day streak</div><button class="more-button" data-delete-habit="${h.id}" aria-label="Delete habit">×</button></div>`).join('')||'<div class="empty-state"><div class="empty-icon">↻</div><h3>No habits yet</h3><p>Start with one small action you can repeat.</p><button class="btn btn-primary" data-action="add-habit">＋ Add habit</button></div>'}</section><section class="panel"><div class="panel-head"><div><h2>This week</h2><div class="panel-sub">Your check-in rhythm</div></div></div><div class="week-strip">${days.map(d=>{let ds=d.toISOString().slice(0,10),n=data.habits.filter(h=>h.checkins.includes(ds)).length;return `<div class="week-day ${n?'done':''}"><span>${d.toLocaleDateString(undefined,{weekday:'short'})}</span><span>${n?'✓':d.getDate()}</span></div>`}).join('')}</div><div class="detail-section"><h3>Habit consistency</h3><div class="detail-progress"><div class="progress-track"><span style="width:${habitRate()}%;background:var(--mint)"></span></div><strong>${habitRate()}%</strong></div><p class="panel-sub">Based on recorded check-ins</p></div><div class="detail-section"><h3>Encouragement</h3><p class="modal-desc">${bestCurrentStreak()>=7?'A full week of consistency is something to be proud of. Keep the rhythm going.':'Every check-in counts. Focus on showing up, even when the step is small.'}</p></div></section></div>`}
 function openHabitForm(){showModal(`<div class="eyebrow">YOUR ROUTINE</div><h2 id="modalTitle">Add a habit</h2><p class="modal-desc">Choose a small action that supports the life you want.</p><form id="habitForm"><div class="form-grid"><div class="field full"><label for="habitName">Habit name *</label><input class="input" id="habitName" name="name" required placeholder="e.g. Stretch for 10 minutes"></div><div class="field"><label for="habitCategory">Category</label><select class="select" id="habitCategory" name="category">${data.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="habitFrequency">Frequency</label><select class="select" id="habitFrequency" name="frequency"><option>Daily</option><option>Weekdays</option><option>Mon, Wed, Fri</option><option>Weekly</option></select></div><div class="field full"><label for="habitGoal">Related goal (optional)</label><select class="select" id="habitGoal" name="goalId"><option value="">No related goal</option>${active().map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select></div></div><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="cancel-modal">Cancel</button><button class="btn btn-primary">Create habit</button></div></form>`);$('#habitForm').onsubmit=saveHabit}
 function saveHabit(e){e.preventDefault();let fd=new FormData(e.currentTarget),name=fd.get('name').trim();if(!name)return;const h={id:id('h'),name,category:fd.get('category'),frequency:fd.get('frequency'),goalId:fd.get('goalId'),emoji:'✧',checkins:[]};data.habits.push(h);addActivity(`Created habit: ${name}`);persist();closeModal();render();toast('Habit added. Start with one check-in today.')}
 function renderCalendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),start=(first.getDay()+6)%7,daysIn=new Date(y,m+1,0).getDate(),prevDays=new Date(y,m,0).getDate();const cells=[];for(let i=0;i<42;i++){let d,month=m,year=y,muted=false;if(i<start){d=prevDays-start+i+1;month=m-1;muted=true}else if(i>=start+daysIn){d=i-(start+daysIn)+1;month=m+1;muted=true}else d=i-start+1;let obj=new Date(year,month,d),ds=`${obj.getFullYear()}-${String(obj.getMonth()+1).padStart(2,'0')}-${String(obj.getDate()).padStart(2,'0')}`;cells.push({d,ds,muted})}const itemsFor=ds=>{let items=[];data.goals.filter(g=>g.deadline===ds&&g.status!=='Completed').forEach(g=>items.push({type:'deadline',title:g.title,sub:'Goal deadline'}));data.goals.forEach(g=>(g.milestones||[]).forEach(ms=>{if(ms.date===ds&&!ms.done)items.push({type:'milestone',title:ms.title,sub:`Milestone · ${g.title}`} )}));data.habits.forEach(h=>{if(h.checkins.includes(ds))items.push({type:'habit',title:h.name,sub:'Habit check-in'})});return items};const selectedItems=itemsFor(selectedDate);return `${pageHeading('Calendar','Keep an eye on deadlines, milestones, and habit check-ins.',`<button class="btn btn-secondary" data-page="goals">View goals</button>`)}<div class="calendar-layout"><section class="panel"><div class="panel-head"><div class="calendar-head"><h2>${calendarDate.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><div class="month-nav"><button data-cal-nav="-1" aria-label="Previous month">‹</button><button data-cal-nav="1" aria-label="Next month">›</button></div></div><span class="panel-sub">Select a date to see its items</span></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${cells.map(c=>{let its=itemsFor(c.ds);return `<button class="calendar-day ${c.muted?'muted-day':''} ${selectedDate===c.ds?'selected':''} ${today===c.ds?'today':''}" data-cal-day="${c.ds}"><span class="day-number">${c.d}</span><span class="day-dots">${its.slice(0,4).map(x=>`<i class="day-dot ${x.type}" title="${esc(x.title)}"></i>`).join('')}</span></button>`}).join('')}</div><div class="panel-sub" style="margin-top:13px"><span class="day-dot" style="display:inline-block"></span> Goal deadline &nbsp; <i class="day-dot habit" style="display:inline-block"></i> Habit check-in &nbsp; <i class="day-dot milestone" style="display:inline-block"></i> Milestone</div></section><section class="panel"><div class="panel-head"><div><h2>${fmt(selectedDate)}</h2><div class="panel-sub">Your scheduled items</div></div></div><div class="calendar-items">${selectedItems.map(it=>`<div class="calendar-item"><span class="calendar-item-mark" style="background:${it.type==='habit'?'var(--mint)':it.type==='milestone'?'var(--amber)':'var(--primary)'}"></span><div><strong>${esc(it.title)}</strong><small>${esc(it.sub)}</small></div></div>`).join('')||'<p class="panel-sub">Nothing scheduled for this date. Enjoy some breathing room.</p>'}</div></section></div>`}
 const achievementDefs=[['first-goal','✧','First step','Create your first goal.'],['first-milestone','⚑','Milestone moment','Complete your first milestone.'],['first-complete','✓','Goal getter','Complete your first goal.'],['quarter-progress','◔','Quarter way there','Reach 25% average progress.'],['half-progress','◑','Halfway hero','Reach 50% average progress.'],['three-quarter-progress','◕','Almost there','Reach 75% average progress.'],['hundred-progress','★','All complete','Every goal reaches 100%.'],['week-streak','🔥','One week strong','Reach a 7-day habit streak.'],['month-streak','🌟','A month of momentum','Reach a 30-day habit streak.'],['five-goals','🏆','Five in the bag','Complete five goals.'],['ten-goals','💎','Ten goals down','Complete ten goals.'],['habit-week','🌱','Steady routine','Check in every day for a week.']];
 function renderAchievements(){let unlocked=data.achievements||[];return `${pageHeading('Achievements','Celebrate the progress you’ve made along the way.')}<section class="stats-grid"><article class="stat-card"><div class="stat-top">Badges unlocked<span class="stat-icon purple">✧</span></div><div class="stat-value">${unlocked.length}<span class="stat-note">of ${achievementDefs.length}</span></div><div class="stat-bottom">Every step counts</div></article><article class="stat-card"><div class="stat-top">Goals completed<span class="stat-icon green">✓</span></div><div class="stat-value">${completed().length}</div><div class="stat-bottom">A reason to feel proud</div></article><article class="stat-card"><div class="stat-top">Best active streak<span class="stat-icon orange">🔥</span></div><div class="stat-value">${bestCurrentStreak()}<span class="stat-note">days</span></div><div class="stat-bottom">Build a little momentum</div></article><article class="stat-card"><div class="stat-top">Milestones completed<span class="stat-icon blue">⚑</span></div><div class="stat-value">${data.goals.flatMap(g=>g.milestones||[]).filter(m=>m.done).length}</div><div class="stat-bottom">On the way to your goals</div></article></section><div class="achievement-grid">${achievementDefs.map(([code,icon,name,desc])=>{let on=unlocked.includes(code);return `<article class="badge-card ${on?'':'locked'}"><div class="badge-icon">${icon}</div><h3>${name}</h3><p>${desc}</p><small>${on?'✦ Unlocked':'🔒 Keep going'}</small></article>`}).join('')}</div>`}
 function renderReports(){const av=pct(),all=data.goals.flatMap(g=>g.milestones||[]),cats=[...new Set(data.goals.map(g=>g.category))];return `${pageHeading('Reports','A simple view of your goals and the work you’ve put in.',`<button class="btn btn-secondary" data-action="print">⤓ Print report</button>`)}<section class="stats-grid"><article class="stat-card"><div class="stat-top">Total goals<span class="stat-icon purple">◎</span></div><div class="stat-value">${data.goals.length}</div><div class="stat-bottom">Across ${cats.length} categories</div></article><article class="stat-card"><div class="stat-top">Active goals<span class="stat-icon blue">↗</span></div><div class="stat-value">${active().length}</div><div class="stat-bottom">Currently in progress</div></article><article class="stat-card"><div class="stat-top">Completed goals<span class="stat-icon green">✓</span></div><div class="stat-value">${completed().length}</div><div class="stat-bottom">${data.goals.length?Math.round(completed().length/data.goals.length*100):0}% completion rate</div></article><article class="stat-card"><div class="stat-top">Average progress<span class="stat-icon orange">◒</span></div><div class="stat-value">${av}%</div><div class="stat-bottom">Across all goals</div></article></section><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Goal progress by category</h2><div class="panel-sub">Average progress across each area</div></div></div><div class="category-analysis">${cats.map(c=>{let list=data.goals.filter(g=>g.category===c),v=Math.round(list.reduce((a,g)=>a+g.progress,0)/list.length);return `<div class="category-line"><span>${esc(c)}</span><div class="progress-track"><span style="width:${v}%"></span></div><strong>${v}%</strong></div>`}).join('')||'<p class="panel-sub">Add goals to see your report.</p>'}</div></section><section class="panel"><div class="panel-head"><div><h2>Habits & milestones</h2><div class="panel-sub">Consistency helps progress grow</div></div></div><div class="goal-summary"><div class="legend-row"><span class="legend-key">Habit check-ins</span><strong>${data.habits.reduce((n,h)=>n+h.checkins.length,0)}</strong></div><div class="legend-row"><span class="legend-key">Habit completion rate</span><strong>${habitRate()}%</strong></div><div class="legend-row"><span class="legend-key">Milestones completed</span><strong>${all.filter(m=>m.done).length}/${all.length}</strong></div><div class="legend-row"><span class="legend-key">Current streak</span><strong>${bestCurrentStreak()} days</strong></div></div></section></div><section class="panel"><div class="panel-head"><div><h2>Goal summary</h2><div class="panel-sub">Your current plan at a glance</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Goal</th><th>Category</th><th>Progress</th><th>Target date</th><th>Status</th></tr></thead><tbody>${data.goals.map(g=>`<tr><td><strong>${esc(g.title)}</strong></td><td>${esc(g.category)}</td><td>${g.progress}%</td><td>${fmt(g.deadline)}</td><td><span class="status-pill ${statusOf(g)}">${g.status==='Active'&&g.deadline<today?'Overdue':esc(g.status)}</span></td></tr>`).join('')}</tbody></table></div></section>`}
 function renderNotifications(){const list=[...data.notifications].sort((a,b)=>b.date.localeCompare(a.date));return `${pageHeading('Notifications','A little nudge when there’s something to notice.',`<button class="btn btn-secondary" data-notify-action="all">Mark all as read</button>`)}<section class="panel">${list.map(n=>`<div class="notification-row ${n.read?'':'unread'}"><div class="notification-icon">${n.type==='complete'?'✓':n.type==='habit'?'↻':n.type==='achievement'?'✧':'◷'}</div><div class="notification-body"><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><small>${fmt(n.date)}</small></div><div class="notification-actions">${n.read?'':`<button data-notify-action="read" data-id="${n.id}">Mark read</button>`}<button data-notify-action="delete" data-id="${n.id}" aria-label="Delete notification">×</button></div></div>`).join('')||'<div class="empty-state"><div class="empty-icon" aria-hidden="true">♧</div><h3>You’re all caught up</h3><p>New updates will show up here.</p></div>'}</section>`}
 function notificationAction(action,nid){if(action==='all')data.notifications.forEach(n=>n.read=true);if(action==='read'){let n=data.notifications.find(n=>n.id===nid);if(n)n.read=true}if(action==='delete')data.notifications=data.notifications.filter(n=>n.id!==nid);persist();render()}
 function renderProfile(){const p=data.profile;return `${pageHeading('Your profile','A snapshot of what you’re working towards.')}<div class="profile-layout"><section class="panel profile-card"><div class="profile-large">${p.photo?`<img src="${esc(p.photo)}" alt="Profile picture for ${esc(p.name)}">`:initials(p.name)}</div><div class="photo-actions"><button class="btn btn-secondary" type="button" data-action="upload-photo">${p.photo?'Change picture':'Add picture'}</button>${p.photo?'<button class="btn btn-quiet" type="button" data-action="remove-photo">Remove</button>':''}<input id="profilePhotoInput" type="file" accept="image/*" hidden></div><h2>${esc(p.name)}</h2><p>${esc(p.email||'')}</p><div class="profile-metrics"><div><strong>${completed().length}</strong><small>Goals completed</small></div><div><strong>${bestCurrentStreak()}</strong><small>Day streak</small></div></div><div class="detail-section"><small class="panel-sub">Member since ${fmt(p.joined)}</small></div></section><section class="panel"><div class="panel-head"><div><h2>Personal information</h2><div class="panel-sub">This profile is stored only in this browser.</div></div></div><form id="profileForm"><div class="form-grid"><div class="field"><label for="profileName">Name</label><input class="input" id="profileName" name="name" required value="${esc(p.name)}"></div><div class="field"><label for="profileEmail">Email</label><input class="input" id="profileEmail" name="email" type="email" value="${esc(p.email||'')}"></div><div class="field full"><label for="profileBio">About you</label><textarea class="textarea" id="profileBio" name="bio">${esc(p.bio||'')}</textarea></div></div><div class="form-actions"><button class="btn btn-primary">Save profile</button></div></form></section></div><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>Recent achievements</h2><div class="panel-sub">Your latest wins</div></div><button class="text-link" data-page="achievements">All achievements →</button></div>${data.achievements.slice(-3).map(code=>{let a=achievementDefs.find(x=>x[0]===code);return a?`<span class="category-pill" style="margin-right:7px">${a[1]} ${a[2]}</span>`:''}).join('')||'<p class="panel-sub">Your first badge is waiting.</p>'}</section>`}
 function saveProfile(e){e.preventDefault();const fd=new FormData(e.currentTarget);data.profile.name=fd.get('name').trim();data.profile.email=fd.get('email').trim();data.profile.bio=fd.get('bio').trim();persist();render();toast('Profile updated.')}
 function saveProfilePhoto(e){const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file for your profile picture.');e.target.value='';return}if(file.size>10*1024*1024){toast('Choose an image smaller than 10 MB.');e.target.value='';return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const max=640,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);data.profile.photo=canvas.toDataURL('image/jpeg',.82);if(!store.save(data)){data.profile.photo='';toast('Could not save the picture. Try a smaller image.');return}updateChrome();render();toast('Profile picture updated.')};img.onerror=()=>toast('That image could not be opened. Please choose another.');img.src=reader.result};reader.readAsDataURL(file);e.target.value=''}
 function renderSettings(){let s=data.settings;return `${pageHeading('Settings','Make Goalspace feel right for you.')}<section class="panel"><div class="panel-head"><div><h2>Appearance</h2><div class="panel-sub">Personalize the way your workspace looks</div></div></div><div class="settings-section"><div class="settings-text"><strong>Color mode</strong><small>Choose light or dark appearance</small></div><div class="theme-options"><button class="theme-swatch ${!s.dark?'selected':''}" data-setting="light">☀ Light</button><button class="theme-swatch ${s.dark?'selected':''}" data-setting="dark">☾ Dark</button></div></div><div class="settings-section"><div class="settings-text"><strong>Accent color</strong><small>Choose the colour used for highlights</small></div><select class="select" id="accentSelect">${[['violet','Iris'],['blue','Ocean'],['mint','Mint'],['coral','Coral']].map(([v,l])=>`<option value="${v}" ${s.accent===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="settings-section"><div class="settings-text"><strong>Motivational quote</strong><small>Show an encouraging note on your dashboard</small></div><button class="switch ${s.quote?'on':''}" data-setting="quote" aria-label="Toggle motivational quote" aria-pressed="${!!s.quote}"></button></div><div class="settings-section"><div class="settings-text"><strong>Reminders</strong><small>Allow local deadline and habit reminders</small></div><button class="switch ${s.reminders?'on':''}" data-setting="reminders" aria-label="Toggle reminders" aria-pressed="${!!s.reminders}"></button></div><div class="settings-section"><div class="settings-text"><strong>Subtle animations</strong><small>Use gentle transitions across the app</small></div><button class="switch ${s.animations?'on':''}" data-setting="animations" aria-label="Toggle animations" aria-pressed="${!!s.animations}"></button></div></section><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>Your data</h2><div class="panel-sub">Export a backup or restore this browser’s starter data</div></div></div><div class="settings-section"><div class="settings-text"><strong>Export your data</strong><small>Download your goals, habits, and settings as a JSON file</small></div><button class="btn btn-secondary" data-action="export">↓ Export</button></div><div class="settings-section"><div class="settings-text"><strong>Import a backup</strong><small>Restore a previously exported Goalspace file</small></div><button class="btn btn-secondary" data-action="import">↑ Import</button><input type="file" id="importFile" accept="application/json,.json" hidden></div><div class="settings-section"><div class="settings-text"><strong>Reset app data</strong><small>Restore the sample goals and remove your changes</small></div><button class="btn btn-danger" data-action="reset">Reset data</button></div></section><p class="panel-sub" style="margin:13px 3px">Your information stays in this browser. Secure sign-in and syncing across devices need a server, which this static version does not use.</p>`}
 function applyAccent(){const colors={violet:'#596df2',blue:'#208bd6',mint:'#27a889',coral:'#e87965'};document.documentElement.style.setProperty('--primary',colors[data.settings.accent]||colors.violet)}
 function handleImport(e){let file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{let imported=JSON.parse(r.result);if(!Array.isArray(imported.goals)||!Array.isArray(imported.habits))throw Error();if(confirm('Replace current Goalspace data with this backup?')){data=imported;persist();render();toast('Backup imported successfully.')}}catch(err){toast('That file is not a valid Goalspace backup.')}e.target.value=''};r.readAsText(file)}
 function changeSetting(k){if(k==='light')data.settings.dark=false;else if(k==='dark')data.settings.dark=true;else data.settings[k]=!data.settings[k];persist();render()}
 function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='goalspace-backup-'+today+'.json';a.click();URL.revokeObjectURL(a.href);toast('Your data backup is ready.')}
 function showModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').hidden=false;$$('[data-action]', $('#modalContent')).forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b));let f=$('input,button', $('#modalContent'));if(f)f.focus()}
 function toast(msg){const n=document.createElement('div');n.className='toast';n.textContent=msg;$('#toastRegion').appendChild(n);setTimeout(()=>n.remove(),3200)}
 function bindGlobal(){document.addEventListener('click',e=>{let target=e.target.closest('[data-page]');if(target&&target.dataset.page){e.preventDefault();editingGoal=null;setPage(target.dataset.page)}const del=e.target.closest('[data-delete-habit]');if(del&&confirm('Delete this habit and its check-in history?')){data.habits=data.habits.filter(h=>h.id!==del.dataset.deleteHabit);persist();render();toast('Habit deleted.')}});$('#returnHome').onclick=()=>{$('#appShell').hidden=true;$('#welcomeScreen').hidden=false;window.scrollTo({top:0});$('#enterWorkspace').focus()};$('#menuToggle').onclick=()=>{let open=$('#sidebar').classList.toggle('open');$('#menuToggle').setAttribute('aria-expanded',String(open))};$('#topAvatar').onclick=()=>{const menu=$('#profileMenu'),open=menu.hidden;menu.hidden=!open;$('#topAvatar').setAttribute('aria-expanded',String(open));if(open)menu.querySelector('[role=menuitem]:not(:disabled)')?.focus()};$$('[data-profile-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.profileAction,menu=$('#profileMenu');menu.hidden=true;$('#topAvatar').setAttribute('aria-expanded','false');if(action==='view')setPage('profile');if(action==='edit'){setPage('profile');setTimeout(()=>$('#profileName')?.focus(),50)}if(action==='photo'){setPage('profile');setTimeout(()=>$('#profilePhotoInput')?.click(),80)}if(action==='remove-photo'&&data.profile.photo){data.profile.photo='';persist();toast('Profile picture removed.')}if(action==='settings')setPage('settings')});document.addEventListener('click',e=>{if(!e.target.closest('.profile-menu-wrap')){$('#profileMenu').hidden=true;$('#topAvatar').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#profileMenu').hidden=true;$('#topAvatar').setAttribute('aria-expanded','false')}});$('#globalSearchBtn').onclick=()=>{setPage('goals');setTimeout(()=>$('#goalSearch')?.focus(),80)};$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target===$('#modalBackdrop'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()})}
 function saveAndBind(){applyAccent();bindGlobal();updateChrome();render();setInterval(()=>{if(!data.settings.reminders)return;let existing=new Set(data.notifications.map(n=>n.message));data.goals.filter(g=>g.status==='Active'&&g.reminder&&daysUntil(g.deadline)===3).forEach(g=>{let msg=`${g.title} is due in 3 days.`;if(!existing.has(msg)){notify('Deadline approaching',msg,'deadline');persist()}})},60000)}
 const welcomeQuotes=[
  ['Great things are done by a series of small things brought together.','Vincent van Gogh'],
  ['You do not have to see the whole staircase, just take the first step.','Martin Luther King Jr.'],
  ['It always seems impossible until it’s done.','Nelson Mandela'],
  ['Success is the sum of small efforts, repeated day in and day out.','Robert Collier'],
  ['The secret of getting ahead is getting started.','Mark Twain'],
  ['It does not matter how slowly you go as long as you do not stop.','Confucius'],
  ['Small daily improvements are the key to staggering long-term results.','James Clear'],
  ['Start where you are. Use what you have. Do what you can.','Arthur Ashe'],
  ['Believe you can and you’re halfway there.','Theodore Roosevelt'],
  ['The future depends on what you do today.','Mahatma Gandhi']
 ];
 function initWelcome(){
   const quote=$('#welcomeQuote'),author=$('#welcomeQuoteAuthor'),screen=$('#welcomeScreen'),app=$('#appShell');
   let current=Math.floor(Math.random()*welcomeQuotes.length);
   const paint=()=>{quote.textContent='“'+welcomeQuotes[current][0]+'”';author.textContent='— '+welcomeQuotes[current][1]};
   paint();
   setInterval(()=>{current=(current+1)%welcomeQuotes.length;paint()},600000);
   $('#enterWorkspace').addEventListener('click',()=>{
     screen.hidden=true;
     app.hidden=false;
     /* Render once the workspace is visible so its first paint never inherits
        a hidden-container state from the welcome screen. */
     setPage('dashboard');
     $('#pageContent').focus();
   });
 }
 /* Attach the welcome action before rendering the workspace so the entry button
    remains usable even if a dashboard widget encounters a browser-specific issue. */
 initWelcome();
 saveAndBind();
})();
